// Validates every variant manifest against the full zod schema (omni-plan §5.3) and checks that each
// variant has its route tree and required assets. Run by `pnpm variants:check` and CI.
import fs from 'node:fs';
import path from 'node:path';

import { parseVariantManifest, VARIANT_IDS } from '@resgrid/config';

const variantsDir = path.resolve(__dirname, '..', 'apps', 'omni', 'variants');
// Generated by scripts/brand-assets (docs/build/app-icons-and-splash.md). Exact sizes matter: the dev/staging icon
// badges are 1024×1024 overlays composited without scaling (with-icon-badge.js), and icon.png is also the iOS store
// icon, which must not have an alpha channel.
const requiredAssets: Record<string, { size?: number; opaque?: boolean }> = {
  'icon.png': { size: 1024, opaque: true },
  'ios-icon-dark.png': { size: 1024 },
  'ios-icon-tinted.png': { size: 1024, opaque: true },
  'adaptive-icon.png': { size: 1024 },
  'adaptive-icon-background.png': { size: 1024, opaque: true },
  'adaptive-icon-monochrome.png': { size: 1024 },
  'splash-icon.png': { size: 1024 },
  'notification-icon.png': { size: 96 },
  'favicon.png': {},
  'desktop-icon.png': { size: 1024 },
  'icon.ico': {},
  'splash-mark.svg': {},
};
const problems: string[] = [];

function pngHeader(file: string): { width: number; height: number; hasAlpha: boolean } | null {
  const bytes = fs.readFileSync(file);
  if (bytes.length < 26 || bytes.toString('ascii', 1, 4) !== 'PNG') return null;
  const colorType = bytes[25];
  return { width: bytes.readUInt32BE(16), height: bytes.readUInt32BE(20), hasAlpha: colorType === 4 || colorType === 6 };
}

for (const id of VARIANT_IDS) {
  const dir = path.join(variantsDir, id);
  try {
    const manifest = parseVariantManifest(JSON.parse(fs.readFileSync(path.join(dir, 'variant.json'), 'utf8')));
    if (manifest.id !== id) problems.push(`${id}: manifest id is "${manifest.id}"`);
  } catch (error) {
    problems.push(`${id}: ${(error as Error).message}`);
  }
  for (const file of ['variant.ts', 'app/_layout.tsx']) {
    if (!fs.existsSync(path.join(dir, file))) problems.push(`${id}: missing ${file}`);
  }
  for (const [asset, rule] of Object.entries(requiredAssets)) {
    const file = path.join(dir, 'assets', asset);
    if (!fs.existsSync(file)) {
      problems.push(`${id}: missing assets/${asset}`);
      continue;
    }
    if (!asset.endsWith('.png')) continue;
    const png = pngHeader(file);
    if (!png) {
      problems.push(`${id}: assets/${asset} is not a PNG`);
    } else if (rule.size && (png.width !== rule.size || png.height !== rule.size)) {
      problems.push(`${id}: assets/${asset} is ${png.width}×${png.height}, expected ${rule.size}×${rule.size}`);
    } else if (png.width !== png.height) {
      problems.push(`${id}: assets/${asset} is not square (${png.width}×${png.height})`);
    } else if (rule.opaque && png.hasAlpha) {
      problems.push(`${id}: assets/${asset} has an alpha channel; it must be opaque`);
    }
  }
}

if (problems.length) {
  console.error(`Variant check failed:\n- ${problems.join('\n- ')}`);
  process.exit(1);
}
console.log(`All ${VARIANT_IDS.length} variants are valid.`);
